import {acquireSystemAppearance} from "/Users/peterkloss/Dev/ACMElabs/design-system/dist/shared/system-appearance.js";
import {createThemeScope} from "/Users/peterkloss/Dev/ACMElabs/design-system/dist/shared/theme-scope.js";
const results=[];const check=(name,actual,expected)=>results.push({name,actual,expected,ok:JSON.stringify(actual)===JSON.stringify(expected)});
function track(doc){const view=doc.defaultView;const original=view.matchMedia.bind(view);const stats={queries:0,active:new Set()};view.matchMedia=query=>{stats.queries++;const media=original(query);const add=media.addEventListener.bind(media),remove=media.removeEventListener.bind(media);media.addEventListener=(name,listener,options)=>{if(name==="change")stats.active.add(listener);add(name,listener,options);};media.removeEventListener=(name,listener,options)=>{if(name==="change")stats.active.delete(listener);remove(name,listener,options);};return media;};return stats;}
const mainStats=track(document);
const frame=document.createElement("iframe");document.body.append(frame);const otherDoc=frame.contentDocument;const frameStats=track(otherDoc);
const main=acquireSystemAppearance(document),second=acquireSystemAppearance(document),foreign=acquireSystemAppearance(otherDoc);
check("document shares one query",mainStats.queries,1);check("document shares one listener",mainStats.active.size,1);check("foreign document owns a separate query",frameStats.queries,1);
const parent=createThemeScope({systemAppearance:main.appearance});parent.setAuthored({theme:"brand",appearance:"dark",density:"compact",locale:"fr"});
const child=createThemeScope({systemAppearance:main.appearance,parent:parent.effective});
check("nearest scope fields inherit",child.effective.get(),parent.effective.get());
child.setAuthored({appearance:"auto",density:"normal"});
check("explicit auto uses actual initial system preference",child.effective.get().resolvedAppearance,"light");
check("explicit normal masks inherited compact",child.effective.get().density,"normal");
const foreignScope=createThemeScope({systemAppearance:foreign.appearance});
window.__themeTest={
 child,foreignScope,
 afterDark(){check("main scope follows native dark preference",child.effective.get().resolvedAppearance,"dark");check("foreign scope follows its document preference",foreignScope.effective.get().resolvedAppearance,"dark");},
 afterLight(){check("main returns to light preference",child.effective.get().resolvedAppearance,"light");child.setAuthored({appearance:undefined});check("clearing auto resumes explicit dark parent",child.effective.get().resolvedAppearance,"dark");main.release();check("first release retains shared listener",mainStats.active.size,1);second.release();check("last release removes document listener",mainStats.active.size,0);check("other document is unaffected",frameStats.active.size,1);},
 afterReleasedDark(){check("released source keeps its final snapshot",main.appearance.get(),"light");check("active foreign source keeps updating",foreign.appearance.get(),"dark");const fresh=acquireSystemAppearance(document);check("reacquire uses current native preference",fresh.appearance.get(),"dark");main.release();check("stale release cannot stop new binding",mainStats.active.size,1);fresh.release();foreign.release();check("all document listeners release",mainStats.active.size+frameStats.active.size,0);
 class Receiver extends HTMLElement {binding;scope;connectedCallback(){this.binding=acquireSystemAppearance(this.ownerDocument);if(this.scope)this.scope.setSystemAppearance(this.binding.appearance);else this.scope=createThemeScope({systemAppearance:this.binding.appearance});}disconnectedCallback(){this.binding?.release();}}
 customElements.define("theme-system-receiver",Receiver);const receiver=document.createElement("theme-system-receiver");document.body.append(receiver);check("connected receiver binds original document",mainStats.active.size,1);otherDoc.adoptNode(receiver);otherDoc.body.append(receiver);check("adoption releases original document",mainStats.active.size,0);check("adoption binds destination document",frameStats.active.size,1);check("adopted receiver reads destination preference",receiver.scope.effective.get().resolvedAppearance,"dark");receiver.remove();check("disconnect releases destination listener",frameStats.active.size,0);frame.remove();window.__results={results};}
};window.__ready=true;

